#!/usr/bin/env python3
"""Bundle source/emails/mockup-reply.{html,txt} into lib/mockup-reply.js for /api/lead.
Run after editing either template:  python3 scripts/build_email.py"""
import json, pathlib, re
root = pathlib.Path(__file__).resolve().parent.parent
html = (root / 'source/emails/mockup-reply.html').read_text()
html = re.sub(r'<!--(?!\[).*?-->\s*', '', html, flags=re.S)  # drop authoring comments
text = (root / 'source/emails/mockup-reply.txt').read_text()
(root / 'lib/mockup-reply.js').write_text(
    '// Generated by scripts/build_email.py from source/emails/ — do not edit by hand.\n'
    f'module.exports = {{\n  html: {json.dumps(html)},\n  text: {json.dumps(text)}\n}};\n')
print('wrote lib/mockup-reply.js')
